const { seg, lerp, eo, eio, TextFx } = kit;
kit.scene('end', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground end-root"><div class="sky-day"></div><div class="halo end-halo"></div>' +
      '<svg class="art" viewBox="0 0 1920 1080"><circle class="end-sun" cx="1560" cy="470" r="150" style="fill:var(--second)"/>' + W.hills(kit, 'end') + '</svg>' +
      '<div class="words end-words" style="left:130px;top:170px;width:1300px"><p class="eyebrow end-eyebrow">First Light is here</p><h1 class="line end-name" style="font-size:166px">Juniper Coffee</h1>' +
      '<svg class="end-mark" viewBox="0 0 900 30" width="900" height="30" style="overflow:visible;margin-top:-14px"><path class="end-rule" pathLength="1" d="M8 18 C150 4 330 27 480 13 S770 6 892 17" style="fill:none;stroke:var(--accent);stroke-width:11;stroke-linecap:round"/></svg>' +
      '<p class="sub end-sub">The spring blend. Order it in the Juniper app.</p></div></div>'));
    const q = (s) => kit.stage.querySelector(s);
    Object.assign(this, { halo: q('.end-halo'), sun: q('.end-sun'), far: q('.end-far'), mid: q('.end-mid'), near: q('.end-near'), mist: q('.end-mist'), haze: q('.end-haze'),
      words: q('.end-words'), eyebrow: q('.end-eyebrow'), rule: q('.end-rule'), sub: q('.end-sub'), name: TextFx.split(q('.end-name')) });
    for (const g of [this.far, this.mid, this.near]) g.style.transformOrigin = '960px 800px';
  },
  render(t, kit) {
    // The hills come to rest as the card lands, then the whole picture keeps one slow push to the end.
    const land = eo(seg(t, -0.2, 1.3)), hold = t / kit.dur, y = lerp(520, 440, eio(seg(t, -0.5, kit.dur)));
    this.sun.setAttribute('cy', y.toFixed(1));
    this.halo.style.transform = 'translate(960px,' + (y - 600).toFixed(1) + 'px) scale(' + (1.08 + 0.05 * hold).toFixed(3) + ')';
    this.far.style.transform = 'translateX(' + (6 * hold).toFixed(2) + 'px) scale(' + (lerp(1.03, 1, land) + 0.006 * hold).toFixed(4) + ')';
    this.mid.style.transform = 'translateX(' + (16 * hold).toFixed(2) + 'px) scale(' + (lerp(1.07, 1, land) + 0.012 * hold).toFixed(4) + ')';
    this.near.style.transform = 'translateX(' + (36 * hold).toFixed(2) + 'px) scale(' + (lerp(1.14, 1, land) + 0.022 * hold).toFixed(4) + ')';
    this.mist.style.transform = 'translateX(' + (-30 * hold).toFixed(2) + 'px)';
    this.haze.style.transform = 'translateX(' + (50 * hold).toFixed(2) + 'px)';
    this.eyebrow.style.opacity = eo(seg(t, 0.1, 0.6)).toFixed(3);
    this.name.forEach((word, i) => {
      const a = eo(seg(t, 0.3 + i * 0.2, 1.0 + i * 0.2));
      word.style.opacity = a.toFixed(3);
      word.style.transform = 'translateY(' + ((1 - a) * 70).toFixed(1) + 'px)';
    });
    this.rule.style.strokeDasharray = eio(seg(t, 1.2, 1.9)).toFixed(3) + ' 2';
    this.rule.style.opacity = t > 1.2 ? 1 : 0;
    const s = eo(seg(t, 1.6, 2.2));
    this.sub.style.opacity = s.toFixed(3);
    this.sub.style.transform = 'translateY(' + ((1 - s) * 28).toFixed(1) + 'px)';
    this.words.style.transform = 'translateY(' + (-1.5 * t).toFixed(2) + 'px)';
  },
});
